	"09010000": {
		names: [{ nominative: "Ὅσιος Μελέτιος ὁ νέος ποὺ ἀσκήτευσε στὸ ὄρος τῆς Μυουπόλεως", short: "Μελέτιος" }],
		biographies: [
			{
				id: "0",
				copyright: "synaxarion.gr",
				text: "Ἀσκήτευσε στὸ ὄρος τῆς Μυουπόλεως.\nΓεννήθηκε κατὰ τὸ ἔτος 1035 στὸ χωριὸ Μουταλάσκη τῆς Καππαδοκίας. Οἱ γονεῖς του ἦταν πολὺ ἐνάρετοι καὶ ὀνομάζονταν Ἰωάννης καὶ Σοφία. Φυσικά, σύμφωνα μὲ τὰ ἱερὰ πιστεύω τους μεγάλωσαν καὶ τὸ παιδὶ τους, τὸν Μελέτιο. Αὐτός, ὅταν μεγάλωσε ᾖλθε στὴν Ἑλλάδα ἐπὶ Ἀλεξίου τοῦ Κομνηνοῦ στὴ Μονὴ τῶν Ταξιαρχῶν τὴν λεγόμενη τοῦ Συμβόλου, τὴν μετέπειτα ἐπονομασθεῖσα τοῦ Ὁσίου Μελετίου. Ἐκεῖ ἀφοῦ ἔλαμψε διὰ τῆς πνευματικῆς του ἀσκήσεως, ἀπεβίωσε εἰρηνικὰ τὸ 1105.",
			},
		],
		info: [],
		refs: [],
		services: [],
		hymns: [],
	},
